CREATE TEMP TABLE IF NOT EXISTS cities (
  id bigserial PRIMARY KEY,
  country_id integer NOT NULL,
  region_id integer,
  name varchar(64) NOT NULL,
  geo_lat double precision,
  geo_lng double precision
);

UPDATE City
SET 
  name = 'Cape Town',
  id_region = 4385
WHERE id_city = 1;

UPDATE City
SET 
  name = 'Pretoria',
  id_region = 4385
WHERE id_city = 2;

UPDATE City
SET 
  name = 'Pietermaritzburg',
  id_region = 4385
WHERE id_city = 3;











SELECT 
    id,
    region_id,
    TRIM(REPLACE(name, E'\r\n', ''))
FROM cities;

CREATE INDEX idx_city_name ON City(name);
CREATE INDEX idx_city_country ON City(id_region);